if(Validator.isNotNull(idFormPrincipale)){
    _log.debug(idFormPrincipale);

    bandoFormPrincipale = bandoFormLocalService.createBandoForm(CounterLocalServiceUtil.increment());
    bandoFormPrincipale.setBandoId(bando.getBandoId());
    bandoFormPrincipale.setFormId(Long.valueOf(idFormPrincipale));
    bandoFormPrincipale.setGroupId(siteGroupId);
    bandoFormPrincipale.setUserId(userId);
    bandoFormPrincipale.setUserName(userFullName);

    formPrincipaleEsistente = gestioneBandiMiddlewareService.getFormPrincipaleBando(bando.getBandoId());
    if(Validator.isNotNull(formPrincipaleEsistente)){
        idFormPrincipaleEsistente = formPrincipaleEsistente.getFormId();
    }
}
// -----------------FORM INTEGRATIVI--------------------------

if(Validator.isNotNull(formIntegrativi)){

    if(Validator.isNotNull(formIntegrativi)){
        for(String idForm : formIntegrativi){
            if(Validator.isNotNull(idForm)){
                BandoForm bandoFormItem = null;
                bandoFormItem = bandoFormLocalService.createBandoForm(CounterLocalServiceUtil.increment());
                bandoFormItem.setBandoId(bando.getBandoId());
                bandoFormItem.setFormId(Long.parseLong(idForm));
                bandoFormItem.setGroupId(siteGroupId);
                bandoFormItem.setUserId(userId);
                bandoFormItem.setUserName(userFullName);
                Form formIntegrativo = formLocalService.getForm(Long.parseLong(idForm));
                List<FormField> listaField = null;
                List<FormField> listaFieldOperatoreEsecuzione = null;
                List<FormField> listaFieldFrontend = null;
                List<FormField> listaFieldAnticipo = null;
                List<FormField> listaFieldSaldo = null;
                List<FormField> listaFieldEsecuzione = null;
                if(Validator.isNotNull(formIntegrativo) && !formIntegrativo.getJson().isEmpty()) {
                    listaField = JsonPathUtil.getFormFields(formIntegrativo.getJson(), GestioneBandiFrontendPortletKeys.TIPO_CUSTOM_FIELD_INTEGRAZIONE_OPERATORE);
                    listaFieldOperatoreEsecuzione = JsonPathUtil.getFormFields(formIntegrativo.getJson(), GestioneBandiFrontendPortletKeys.TIPO_CUSTOM_FIELD_INTEGRAZIONE_OPERATORE_ESECUZIONE);
                    listaFieldFrontend = JsonPathUtil.getFormFields(formIntegrativo.getJson(), GestioneBandiFrontendPortletKeys.TIPO_CUSTOM_FIELD_INTEGRAZIONE_FRONTEND);
                    listaFieldAnticipo = JsonPathUtil.getFormFields(formIntegrativo.getJson(), GestioneBandiFrontendPortletKeys.TIPO_CUSTOM_FIELD_ANTICIPO);
                    listaFieldSaldo = JsonPathUtil.getFormFields(formIntegrativo.getJson(), GestioneBandiFrontendPortletKeys.TIPO_CUSTOM_FIELD_SALDO);
                    listaFieldEsecuzione = JsonPathUtil.getFormFields(formIntegrativo.getJson(), GestioneBandiFrontendPortletKeys.TIPO_CUSTOM_FIELD_ESECUZIONE);
                }

                if(Validator.isNotNull(listaField) && !listaField.isEmpty()) {
                    bandoFormItem.setTipoForm(TipoFormEnum.INTEGRAZIONE_OPERATORE.name());
                }
                else if (Validator.isNotNull(listaFieldOperatoreEsecuzione) && !listaFieldOperatoreEsecuzione.isEmpty()) {
                    bandoFormItem.setTipoForm(TipoFormEnum.INTEGRAZIONE_OPERATORE_ESECUZIONE.name());
                }
                else if (Validator.isNotNull(listaFieldFrontend) && !listaFieldFrontend.isEmpty()) {
                    bandoFormItem.setTipoForm(TipoFormEnum.INTEGRAZIONE_FRONTEND.name());
                }
                else if (Validator.isNotNull(listaFieldAnticipo) && !listaFieldAnticipo.isEmpty()) {
                    boolean isIntegrazione = checkFormIntegrazione(listaFieldAnticipo, formIntegrativo.getJson());
                    if (isIntegrazione) {
                        bandoFormItem.setTipoForm(TipoFormEnum.ESECUZIONE_ANTICIPO_INTEGRAZIONE.name());
                    }
                }
                else if (Validator.isNotNull(listaFieldSaldo) && !listaFieldSaldo.isEmpty()) {
                    boolean isIntegrazione = checkFormIntegrazione(listaFieldSaldo, formIntegrativo.getJson());
                    if (isIntegrazione) {
                        bandoFormItem.setTipoForm(TipoFormEnum.ESECUZIONE_SALDO_INTEGRAZIONE.name());
                    }
                }
                else if(Validator.isNotNull(listaFieldEsecuzione) && !listaFieldEsecuzione.isEmpty()) {
                    boolean isIntegrazione = checkFormIntegrazione(listaFieldEsecuzione, formIntegrativo.getJson());
                    if (isIntegrazione) {
                        bandoFormItem.setTipoForm(TipoFormEnum.ESECUZIONE_INTEGRAZIONE.name());
                    }
                }
                else {
                    bandoFormItem.setTipoForm(TipoFormEnum.INTEGRAZIONE.name());
                }
                listaBandoFormIntegrativi.add(bandoFormItem);
            }
        }
    }

}

