public List<IstanzaDomandaBando> getIstanzeIntegrativeByDomandaBandoIdAndStato(long domandaBandoId, String stato) {
    IstanzaDomandaBandoFilters filters = new IstanzaDomandaBandoFilters();
    List<String> tipoForms = new ArrayList<>();
    tipoForms.add(TipoFormEnum.INTEGRAZIONE.name());
    tipoForms.add(TipoFormEnum.ESECUZIONE_INTEGRAZIONE.name());
    tipoForms.add(TipoFormEnum.ESECUZIONE_ANTICIPO_INTEGRAZIONE.name());
    tipoForms.add(TipoFormEnum.ESECUZIONE_SALDO_INTEGRAZIONE.name());
    filters.setStatoIn(Collections.singletonList(stato));
    return istanzaDomandaBandoLocalService.getIstanzeDomandeBandoByDomandaBandoIdAndTipoForms(domandaBandoId, tipoForms, filters, QueryUtil.ALL_POS, QueryUtil.ALL_POS);
}

public String getTipoIntegrazioneDomanda(String processInstanceId){
    String tipoIntegrazione = "";
    List<VariableInstance> vars = camundaClient.getVariablesByProcessInstanceId(processInstanceId);
    boolean variabileTrovata = false;

    if(ListUtil.isNotNull(vars) && ListUtil.isNotEmpty(vars)){
        Iterator<VariableInstance> it = vars.iterator();

        while(it.hasNext() && !variabileTrovata){
            VariableInstance variableInstance = it.next();

            if(Validator.isNotNull(variableInstance) && variableInstance.getName().equalsIgnoreCase(CustomProcessVariables.TIPO_INTEGRAZIONE)){
                variabileTrovata = true;
                tipoIntegrazione = (String) variableInstance.getValue();
            }
        }
    }

    return tipoIntegrazione;
}

public long countIstanzeIntegrativeByDomandaBandoIdNotStati(long domandaBandoId, List<String> stati) {
    IstanzaDomandaBandoFilters filters = new IstanzaDomandaBandoFilters();
    filters.setStatoNotIn(stati);
    filters.setEscludiIstanzeTerminiCompilazioneScaduti(true);
    List<String> tipoForms = new ArrayList<>();
    tipoForms.add(TipoFormEnum.INTEGRAZIONE.name());
    tipoForms.add(TipoFormEnum.ESECUZIONE_INTEGRAZIONE.name());
    tipoForms.add(TipoFormEnum.ESECUZIONE_ANTICIPO_INTEGRAZIONE.name());
    tipoForms.add(TipoFormEnum.ESECUZIONE_SALDO_INTEGRAZIONE.name());
    return istanzaDomandaBandoLocalService.countIstanzeDomandeBandoByDomandaBandoIdAndTipoForm(domandaBandoId, tipoForms, filters);
}

